"""Factual fourteen-section report and regime-by-task scientific figure."""
from common import *
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
def main():
    out=output();support=read(out/'WP05_REGIME_SUPPORT.csv');counts=read(out/'WP05_REGIME_COUNTS.csv');prev=read(out/'WP05_REGIME_PREVALENCE.csv');regs=read(out/'WP05_REGRESSION_RESULTS.csv');directions=read(out/'WP05_BORG_DIRECTION_COUNTS.csv');pm=read(out/'WP05_PARTICIPANT_REGIME_MEANS.csv')
    s0=json.loads((out/'verification/stage0.json').read_text());s1=json.loads((out/'verification/stage1_manifest.json').read_text());s2=json.loads((out/'verification/stage2_manifest.json').read_text());s1audit=json.loads((out/'verification/S1_audit_checks.json').read_text());family=json.loads((out/'verification/family_identity_checks.json').read_text())
    def ci(r):return f"{float(r['estimate']):.6f} [{float(r['ci_lower']):.6f}, {float(r['ci_upper']):.6f}]"
    def tab(head,rr):return '\n'.join(['| '+' | '.join(head)+' |','|'+'|'.join(['---']*len(head))+'|']+['| '+' | '.join(map(str,row))+' |' for row in rr])+'\n'
    def reg(term,variant='shared'):return next(r for r in regs if r['variant']==variant and r['term']==term)
    def sup(t,g,o='famB_ACC_agreement',cohort='shared'):return next(r for r in support if (r['cohort'],r['task'],r['famB_regime'],r['outcome'])==(cohort,t,g,o))
    primary=[r for r in support if r['cohort']=='shared' and r['task']!='Pooled_secondary' and r['outcome']=='famB_ACC_agreement']
    matched=[r for r in support if r['cohort']=='matched_tasks' and r['task']!='Pooled_secondary' and r['outcome']=='famB_ACC_agreement']
    assert all(sup(t,'FAM_B_UP')['status']=='SUPPORTED' and sup(t,'FAM_B_DOWN')['status']=='DIRECTIONALLY_CONTRADICTED' for t in ('Composite','Harnessing'))
    assert all(sup(t,'FAM_B_UP',cohort='matched_tasks')['status']=='SUPPORTED' and sup(t,'FAM_B_DOWN',cohort='matched_tasks')['status']=='DIRECTIONALLY_CONTRADICTED' for t in ('Composite','Harnessing'))
    lines=['# WP-05 structural active-work regime diagnostic','',
    'Executor: Codex, GPT-6-based agent per runtime instructions. Exact served model identifier and reasoning-effort setting are not exposed. No subagents were used. All new outputs are confined to `the selected output directory`. No publication, manuscript-revision, or Controller verdict is assigned.','',
    '## 1. Prior verified state','',
    'PASS: original Stage-A prediction and Stage-B result hashes verified; all 67 previously manifested WP-04 files verified; original FAM-A/FAM-B ACC estimates and matched differences reproduced from authoritative WP-02 transition evidence using the original participant bootstrap. Numerical tolerance is 1e-10 against frozen tables. WP-04 outcome values are not used in WP-05.','',
    tab(['Endpoint','Contrast','Participants','Estimate [95% CI]'],[[r['endpoint'],r['contrast'],r['participants'],ci(r)] for r in s0['results']]),
    '## 2. Post-WP04 motivation and non-preregistered status','',
    'WP-04 did not support its frozen arm-versus-torso alignment proxy explanation. This motivated the present targeted diagnostic: distinguish FAM-B upward and downward model-generated active-work regimes and inspect whether their empirical agreement and exposure frequencies explain the aggregate task pattern descriptively. WP-05 was designed after prior outcome inspection. It is not preregistered, not prespecified before the original study, and not outcome-blind discovery. The implementation was frozen in `WP05_METHOD_SPEC.md` before new inferential calculations. No new explanatory variables or sensors were searched.','',
    '## 3. Frozen regime definition','',
    'FAM_B_UP: original parameter-robust predicted sign >0. FAM_B_DOWN: sign <0. FAM_B_TIE: sign=0. Every included prediction was verified against all 20 unique original (lambda, mu) parameter pairs; signs were identical across the entire envelope and matched the original prediction field. FAM-A was structurally +1 for every shared transition. No direction tolerance or model-state threshold was introduced.','',
    f"Stage 1 used only a sealed keys-only WP-04 cohort projection and the original frozen model predictions/manifest, plus its method/code provenance. It did not open Borg or agreement evidence. Regime SHA-256: `{s1['regime_sha256']}`. Method SHA-256: `{s1['method_spec_sha256']}`. The write-once regime seal preceded the Stage-2 empirical join. The clean-rerun file-access audit separately enforces this input boundary. This process separation does not imply discovery blindness.",'',
    tab(['Task','Regime','Participants with regime','Transitions'],[[r['task'],r['famB_regime'],r['participants'],r['transitions']] for r in counts if r['transition_index']=='ALL']),
    '## 4. Analytic cohort','',
    'Exactly the WP-04 shared cohort: 37 distinct participants, 222 adjacent active-work transitions; Composite 32 participants/121 transitions; Harnessing 27/101. There are 22 participants represented in both tasks (165 transitions). No transition was added, imputed, reclassified by outcomes, or excluded in this WP. No TIE regime exists. A participant can contribute to both regimes and tasks; table participant counts therefore must not be summed as independent people.','',
    'Each empirical row preserves participant/task/from/to IDs and transition index j=1–4, and uses only the authoritative WP-02 observed Borg sign and agreements. The join verifies the original agreement algebra and common observed sign between families. Exact data are saved in `WP05_PAIRED_TRANSITIONS.csv`; original prediction IDs and per-pair checks are in `verification/stage1_prediction_provenance.csv`.','',
    '## 5. Regime prevalence','',
    'down_share is the number of DOWN transitions divided by all eligible FAM-B ACC transitions within participant/task. Task estimates equally weight participant shares; matched differences resample matched participant differences, preserving both tasks. Intervals use the original 10,000 participant-bootstrap percentile procedure and seed 20260926. Denominators and individual shares are saved.','',
    tab(['Cohort','Contrast','Participants','Mean share or difference [95% CI]'],[[r['cohort'],r['contrast'],r['participants'],ci(r)] for r in prev]),
    'Harnessing has greater participant-level exposure to DOWN. The matched Composite-minus-Harnessing interval is entirely below zero. Transition fractions (35/121 versus 48/101) differ slightly from participant-weighted shares because participants have differing eligible-transition counts. No causal task effect is inferred.','',
    '## 6. Empirical UP/DOWN support','',
    'For each task/regime, first average transition agreements within participant, then average those participant means. A participant without a transition in that regime is absent from that conditional estimate. The original support rule is applied to the FAM-B agreement interval: lower>0 supported; upper<0 directionally contradicted; otherwise evidence-insufficient.','',
    tab(['Task','Regime','Participants','Transitions','B agreement [95% CI]','Status'],[[r['task'],r['famB_regime'],r['participants'],r['transitions'],ci(r),r['status']] for r in primary]),
    'UP is supported in both tasks; DOWN is directionally contradicted in both tasks. These are ordinal agreement findings for model-generated state direction, not physiological recovery or state-magnitude validation. Exact observed Borg signs are:','',
    tab(['Task','Regime','Observed −1','Observed 0','Observed +1'],[[r['task'],r['famB_regime'],r['observed_down'],r['observed_tie'],r['observed_up']] for r in directions if r['cohort']=='shared' and r['task']!='Pooled_secondary']),
    'Pooled-across-task results are secondary descriptive summaries. All regime transitions are first averaged within each participant across tasks, then participants are equally weighted and resampled.','',
    tab(['Regime','Participants','Transitions','B agreement [95% CI]','Status'],[[r['famB_regime'],r['participants'],r['transitions'],ci(r),r['status']] for r in support if r['cohort']=='shared' and r['task']=='Pooled_secondary' and r['outcome']=='famB_ACC_agreement']),
    '## 7. Exact FAM-A versus FAM-B contrast','',
    'For signs −1/0/+1 the frozen score is predicted_sign × observed_sign. A predicts +1 throughout. On every UP transition B also predicts +1, so A and B agreement are algebraically identical for every possible observed sign. All 139 UP rows empirically verify this identity. With no TIE regime, nonzero model-family disagreement occurs only in DOWN: 43 rows, zero outside DOWN. On DOWN, delta = B−A = −2×observed_sign, verified rowwise.','',
    tab(['Task','Regime','A agreement [95% CI]','B agreement [95% CI]','Paired B−A [95% CI]'],[[t,g,ci(sup(t,g,'famA_ACC_agreement')),ci(sup(t,g)),ci(sup(t,g,'delta_agreement'))] for t in ('Composite','Harnessing') for g in ('FAM_B_UP','FAM_B_DOWN')]),
    'FAM-B’s additional downward active-work behavior removes directional agreement relative to FAM-A in both tasks in this cohort. Zero UP delta is an exact structural identity, not an empirical failure to detect a contrast. Family-contrast support-status fields use the original zero-centered interval convention; interpret negative DOWN deltas as a family contrast, not a separate physiological claim.','',
    '## 8. Conditioned task analysis','',
    'OLS: B agreement ~ DOWN + Composite + DOWN×Composite + transition_index, with intercept. Harnessing/UP are reference categories. DOWN is its within-Harnessing regime contrast; Composite is the task contrast within UP; interaction is the difference in regime contrasts across tasks. Composite+interaction reports the task contrast within DOWN. This is descriptive structural conditioning, not causal mediation.','',
    tab(['Term','Coefficient [95% participant-bootstrap CI]'],[[r['term'],ci(r)] for r in regs if r['variant']=='shared']),
    f"Descriptive R²={float(reg('DOWN')['descriptive_R2']):.6f}. DOWN has a large negative association with agreement; task, interaction, and the derived within-DOWN task contrast each have intervals spanning zero. The interaction point estimate is small relative to the DOWN contrast, but its interval is not an equivalence result and still allows task heterogeneity. Equal transition weights define the regression estimand; participants define resampling uncertainty.",'',
    '## 9. Model-magnitude sensitivity','',
    '**NOT TESTABLE.** Original frozen observed-transition predictions store only direction for each of the 20 parameter pairs (`lambda`, `mu`, `direction`), not signed state changes or endpoint state values. The prediction-robustness artifact stores the grid and counts, not observed trajectories. Obtaining magnitudes would require rerunning the original propagation, which the requested availability rule disallows for this component. Synthetic WP-03 S1 states cannot stand in for observed transitions. Therefore no min/max/median state-change table or magnitude tertiles are fabricated. Availability evidence is in `WP05_MODEL_MAGNITUDE_STATUS.json`; `WP05_MODEL_MAGNITUDE.csv` is intentionally absent. Whether DOWN disagreement is confined to near-zero observed-model changes remains unresolved.','',
    '## 10. S1 decision-path audit','',
    'All 40 frozen S1 schedule state/peak rows were exactly reproduced for the original 20 parameter pairs using the unchanged evaluator at Decimal precision 100. H→L contains one downward active-work transition in every original trace. Nevertheless, that decrease is not necessary for its lower peak: replacing every active-work decrease by no change preserves both peaks, their gap and the strict H→L preference in all 20 pairs.','',
    f"Let q=exp(−lambda D). The peak gap is (E_L−E_R)(1−q)q>0, independent of mu, ranging from {s1audit['peak_gap_min']} to {s1audit['peak_gap_max']} kcal/min model state. It arises because L first raises the inherited state entering H, while H first starts at E_R. Finite target-dependent increase, inherited state/path dependence and the peak objective determine the formal preference. The later source decrease occurs below the already attained peak. No rest update is involved.",'',
    'The no-decrease operation is solely a diagnostic counterfactual, not a source-faithful alternative model. Generic ACC is a coarse evidence mapping for S1’s quantitative increase/path/peak dependency. DOWN weakness alone does not invalidate its formal preference; UP directional support alone does not validate quantitative magnitudes, path dependence, or practical benefit. Detailed algebra, traces and mapping implications are saved in `WP05_S1_DECISION_PATH_AUDIT.md`. No manuscript-correction decision is made.','',
    '## 11. Robustness','',
    'The both-task participant restriction retains the regime support pattern:','',
    tab(['Task','Regime','Participants','Transitions','B agreement [95% CI]','Status'],[[r['task'],r['famB_regime'],r['participants'],r['transitions'],ci(r),r['status']] for r in matched]),
    'Regression sensitivities (complete coefficients and within-DOWN task contrasts are in the saved CSV):','',
    tab(['Sensitivity','DOWN [95% CI]','Composite [95% CI]','DOWN×Composite [95% CI]'],[[variant,ci(reg('DOWN',variant)),ci(reg('Composite_minus_Harnessing',variant)),ci(reg('DOWN_x_Composite',variant))] for variant in ('shared_omit_transition_index','matched_tasks','matched_tasks_omit_transition_index')]),
    'The regime interpretation is unchanged when transition index is omitted or analysis is restricted to both-task participants. Exact regime counts by index are:','',
    tab(['Task','Index','UP','DOWN','TIE'],[[t,i]+[next(r['transitions'] for r in counts if r['task']==t and r['transition_index']==str(i) and r['famB_regime']==g) for g in ('FAM_B_UP','FAM_B_DOWN','FAM_B_TIE')] for t in ('Composite','Harnessing') for i in range(1,5)]),
    'Every bootstrap draw selects participant IDs: regression draws carry all eligible transitions and both tasks together; task/regime estimates draw the sorted IDs eligible for that conditional group, each with its full block. Pooled summaries collapse tasks within person. Matched prevalence resamples paired person-level differences. No transition-level bootstrap is used. Regression weighted sufficient-statistic estimates are checked against literal repeated participant blocks, and conditional summaries are checked against original participant-mean resampling. All 10,000 draws in every regression were full rank. Clean-rerun deterministic checks and actual Stage-1 access audit are saved in `verification/`.','',
    '## 12. Supported conclusions','',
    'The factual pattern meets the requested structural-regime-boundary pattern: UP supported in both tasks, DOWN contradicted in both, higher DOWN prevalence in Harnessing, and no directionally informative residual task/interaction contrast after conditioning. Evidence is consistent with a model-structural active-work regime boundary; aggregate task conditionality is associated with differing exposure to that regime. All family disagreement in the shared cohort is localized exactly to non-tied observed directions within DOWN. The result supports this targeted descriptive decomposition, not a numerical causal proportion explained.','',
    '## 13. Unsupported conclusions','',
    'The analysis does not establish causal irrelevance of task, equality of within-regime validity, universal failure of every DOWN transition, practical model-state magnitudes, measured physiological recovery during active work, a new fatigue predictor, or transportability outside the original eligibility domain. It cannot answer whether DOWN errors are confined to near-zero model changes. It does not show that S1’s formal preference requires DOWN or that UP agreement validates S1’s quantitative decision. No model was fitted to Borg, no scenario was changed, no new sensor feature was introduced, and no publication/manuscript verdict follows.','',
    '## 14. Remaining limitations','',
    'This is a post-WP04 targeted analysis selected after observing prior results; bootstrap intervals are diagnostic rather than preregistered confirmatory guarantees. Multiple related targeted summaries are reported together without familywise confirmatory claims. There are 37 people, fewer within each regime/task; subgroup membership differs and repeated transitions are dependent. Confidence intervals spanning zero do not establish equivalence, and the interaction interval permits meaningful heterogeneity. Regime and predictor sign are model-defined, while Borg direction is discrete and frequently tied; the negative DOWN score reflects observed upward Borg trends within those rows, not a direct physiological assay.','',
    'Aggregation weights differ: original task support and regime support weight eligible participant means, whereas regression weights transitions and task prevalence weights participant shares. Subgroup means cannot be naively mixed using aggregate transition proportions to recover participant-level task means. Matched restriction addresses cohort composition only descriptively. Original parameter-envelope robustness guarantees signs at the 20 frozen source pairs, not continuous parameter-space validity or calibrated magnitudes. No observed state magnitudes were preserved, limiting the requested near-zero-change sensitivity. S1 is synthetic and many formal peak gaps are extremely small; no practical benefit threshold exists. The root project has no Git metadata; preservation is verified by a full SHA-256 before/after comparison of existing non-Git files instead. Exact served model/effort metadata are unavailable.','']
    (out/'WP05_RESULT_SUMMARY.md').write_text('\n'.join(lines),encoding='utf-8')
    # Main figure: observed participant means, with participant-bootstrap uncertainty.
    fig,axes=plt.subplots(1,2,figsize=(10,4.8),sharey=True,layout='constrained')
    colors={'Composite':'#3174a1','Harnessing':'#c1782b'}
    for ax,t in zip(axes,('Composite','Harnessing')):
        pp=[r for r in pm if r['cohort']=='shared' and r['task']==t and r['outcome']=='famB_ACC_agreement']
        for p in sorted({r['participant_id'] for r in pp}):
            dd={r['famB_regime']:float(r['participant_mean']) for r in pp if r['participant_id']==p}
            if len(dd)==2:ax.plot([0,1],[dd['FAM_B_UP'],dd['FAM_B_DOWN']],color='#cccccc',lw=.65,zorder=1)
        for j,g in enumerate(('FAM_B_UP','FAM_B_DOWN')):
            yy=sorted(float(r['participant_mean']) for r in pp if r['famB_regime']==g)
            # Deterministic spread is only a display offset; no extra observations.
            jitter=np.linspace(-.08,.08,len(yy))
            ax.scatter(j+jitter,yy,color=colors[t],s=19,alpha=.65,zorder=2)
            r=sup(t,g);est=float(r['estimate'])
            ax.errorbar(j+.16,est,yerr=[[est-float(r['ci_lower'])],[float(r['ci_upper'])-est]],fmt='D',color='black',capsize=5,zorder=3)
            ax.text(j,-1.17,f"n={r['participants']} people\n{r['transitions']} transitions",ha='center',fontsize=9)
        ax.axhline(0,color='gray',ls='--',lw=1);ax.set(title=t,xticks=[0,1],xticklabels=['UP','DOWN'],xlim=(-.35,1.4),ylim=(-1.3,1.08));ax.grid(axis='y',alpha=.15)
    axes[0].set_ylabel('Participant mean FAM-B directional agreement')
    fig.suptitle('FAM-B active-work regimes on the exact shared cohort',fontsize=13)
    fig.supxlabel('Points: participant means; lines: participants in both regimes; black: mean and 95% participant-bootstrap CI',fontsize=9)
    fig.savefig(out/'figures/WP05_regime_by_task.png',dpi=170,metadata={'Software':'WP05 saved report.py'});plt.close(fig)
    print('Saved fourteen-section factual report and regime-by-task figure.')
if __name__=='__main__':main()
